best: tuple[float, frozenset[str]] = (-1.0, frozenset())
for k in range(len(projects) + 1):
    for combo in combinations(projects, k):
        plan = frozenset(p.pid for p in combo)
        if allowed(projects, plan, budget):
            total = sum(risk_avoided(p, assets) for p in combo)
            if total > best[0]:
                best = (total, plan)
return best

plan = frozenset(p.pid for p in projects if p.must_do)
for p in sorted(projects, key=lambda p: risk_avoided(p, assets), reverse=True):
    if allowed(projects, plan | {p.pid}, budget):
        plan = plan | {p.pid}
return sum(risk_avoided(p, assets) for p in projects if p.pid in plan), plan
